const NL = String.fromCharCode(10);
const DQ = String.fromCharCode(34);
const FAIL = '조회 실패';
const sd = $getWorkflowStaticData('global');
let isSchedule = false;
try { isSchedule = $('매일 오전 8시').isExecuted && $execution.mode === 'production'; } catch (e) {}
const kst = (d, o) => new Intl.DateTimeFormat('sv-SE', Object.assign({ timeZone: 'Asia/Seoul' }, o || {})).format(d);
const now = new Date();
const today = kst(now);
const wk = new Intl.DateTimeFormat('ko-KR', { timeZone: 'Asia/Seoul', weekday: 'short' }).format(now);
if (isSchedule && sd.lastSentDate === today) { return []; }
const get = (name) => { try { const a = $(name).all(); return a.length ? a[0].json : null; } catch (e) { return null; } };
const cut = (s, n) => (s.length > n ? s.slice(0, n - 1) + '…' : s);
const num = (n, d) => Number(n).toLocaleString('en-US', { minimumFractionDigits: d, maximumFractionDigits: d });
const sgn = (n, d) => (n >= 0 ? '+' : '') + n.toFixed(d) + '%';
const msgs = [];
const push = (text, url, btn) => msgs.push({ template_object: JSON.stringify({ object_type: 'text', text: cut(text, 200), link: { web_url: url, mobile_web_url: url }, button_title: btn || '열기' }) });

// 1) 반도체 시세
const chart = (j) => { try { const r = j.chart.result[0]; const ts = r.timestamp; const cl = r.indicators.quote[0].close; const p = []; for (let i = 0; i < ts.length; i++) { if (cl[i] != null) p.push({ t: ts[i], c: cl[i] }); } if (p.length < 2) return null; const a = p[p.length - 2]; const b = p[p.length - 1]; return { close: b.c, chg: (b.c / a.c - 1) * 100, date: new Intl.DateTimeFormat('sv-SE', { timeZone: r.meta.exchangeTimezoneName || 'America/New_York' }).format(new Date(b.t * 1000)) }; } catch (e) { return null; } };
const sox = chart(get('SOX 지수 조회') || {});
const etf = chart(get('SOXX ETF 조회') || {});
const l1 = sox ? 'SOX 지수(' + sox.date + ' 종가) ' + num(sox.close, 2) + ' (' + sgn(sox.chg, 2) + ')' : 'SOX 지수: ' + FAIL;
const l2 = etf ? 'SOXX ETF[지수 아님](' + etf.date + ') $' + num(etf.close, 2) + ' (' + sgn(etf.chg, 2) + ')' : 'SOXX ETF: ' + FAIL;
push('☀️ ' + today + '(' + wk + ') 미국 반도체·CPI 브리핑' + NL + l1 + NL + l2 + NL + '출처: Yahoo Finance(비공식·지연 가능)', 'https://finance.yahoo.com/quote/%5ESOX', '시세 보기');

// 2) CPI (BLS 공식)
const SCHEDULE = { '2026-10': '2026-11-10', '2026-11': '2026-12-10', '2027-01': '2027-02-11', '2027-02': '2027-03-10', '2027-03': '2027-04-13', '2027-04': '2027-05-12', '2027-05': '2027-06-10', '2027-06': '2027-07-14', '2027-07': '2027-08-11', '2027-08': '2027-09-14', '2027-09': '2027-10-14', '2027-10': '2027-11-10', '2027-11': '2027-12-10' };
let cpiPeriod = null;
try {
  const j = get('BLS CPI 조회');
  const S = j.Results.series;
  const ser = (id) => { const m = {}; for (const d of S.find((x) => x.seriesID === id).data) { const v = parseFloat(d.value); if (/^M(0[1-9]|1[0-2])$/.test(d.period) && !isNaN(v)) { m[d.year + '-' + d.period.slice(1)] = v; } } return m; };
  const hSA = ser('CUSR0000SA0'); const hNSA = ser('CUUR0000SA0'); const cSA = ser('CUSR0000SA0L1E'); const cNSA = ser('CUUR0000SA0L1E');
  const keys = Object.keys(hSA).sort();
  const cur = keys[keys.length - 1];
  const shift = (k, n) => { const m = Number(k.slice(5, 7)) - 1 + n; const y = Number(k.slice(0, 4)) + Math.floor(m / 12); return y + '-' + String(((m % 12) + 12) % 12 + 1).padStart(2, '0'); };
  const yoy = (nsa) => { const b = nsa[shift(cur, -12)]; return nsa[cur] != null && b != null ? ((nsa[cur] / b - 1) * 100).toFixed(1) + '%' : FAIL; };
  const mom = (sa) => { const b = sa[shift(cur, -1)]; return sa[cur] != null && b != null ? sgn((sa[cur] / b - 1) * 100, 1) : FAIL; };
  const stored = sd.lastCpiPeriod;
  const tag = !stored ? '기존 수치(최초 조회)' : (stored !== cur ? '🆕 신규 발표' : '기존 수치');
  const nxt = shift(cur, 1);
  const rel = SCHEDULE[nxt];
  const nextLine = '다음 발표: ' + (rel ? rel + '(' + nxt + '월분)' + (rel < today ? ' ※일정 확인 필요' : '') : nxt + '월분 일정 미등록');
  cpiPeriod = cur;
  push('🇺🇸 미국 CPI ' + cur + '월분 ' + tag + NL + '헤드라인 전년비 ' + yoy(hNSA) + ' / 전월비 ' + mom(hSA) + NL + '근원 전년비 ' + yoy(cNSA) + ' / 전월비 ' + mom(cSA) + NL + nextLine + NL + '출처: BLS(공식)', 'https://www.bls.gov/cpi/', 'BLS CPI');
} catch (e) {
  push('🇺🇸 미국 CPI: ' + FAIL + ' (BLS API)', 'https://www.bls.gov/cpi/', 'BLS CPI');
}

// 3) 뉴스 (Google News RSS, 최근 24시간, 최대 3건)
const out = [];
try {
  const n = get('반도체 뉴스 RSS');
  const xml = n && n.data;
  if (!xml || xml.indexOf('<rss') < 0) { throw new Error('rss'); }
  const dec = (s) => s.split('<![CDATA[').join('').split(']]>').join('').split('&lt;').join('<').split('&gt;').join('>').split('&quot;').join(DQ).split('&#39;').join(String.fromCharCode(39)).split('&amp;').join('&');
  const tag = (b, t) => { const m = new RegExp('<' + t + '[^>]*>([^]*?)</' + t + '>').exec(b); return m ? dec(m[1].trim()) : ''; };
  const re = new RegExp('<item>([^]*?)</item>', 'g');
  const items = []; let m;
  while ((m = re.exec(xml)) !== null) { const b = m[1]; let title = tag(b, 'title'); const source = tag(b, 'source'); if (source && title.endsWith(' - ' + source)) { title = title.slice(0, title.length - source.length - 3); } items.push({ title, link: tag(b, 'link'), source, pub: new Date(tag(b, 'pubDate')) }); }
  const sent = sd.sentNews || [];
  const seen = new Set();
  const co = ['Nvidia', 'AMD', 'Broadcom', 'Micron', 'Intel'];
  const fresh = items.filter((x) => x.link && !isNaN(x.pub) && now - x.pub <= 86400000 && !sent.includes(x.link)).filter((x) => { const k = x.title.toLowerCase().slice(0, 60); if (seen.has(k)) { return false; } seen.add(k); return true; });
  fresh.forEach((x) => { const t = x.title.toLowerCase(); x.co = co.find((c) => new RegExp('(^|[^a-z])' + c.toLowerCase() + '([^a-z]|$)').test(t)) || ''; x.score = x.co ? 1 : 0; });
  fresh.sort((a, b) => b.score - a.score || b.pub - a.pub);
  for (const x of fresh) { if (x.co && out.length < 3 && !out.some((o) => o.co === x.co)) { out.push(x); } }
  for (const x of fresh) { if (out.length < 3 && !out.includes(x)) { out.push(x); } }
  if (out.length === 0) { push('📰 최근 24시간 신규 반도체 뉴스 없음(Google News RSS)', 'https://news.google.com/', 'Google News'); }
  out.forEach((x, i) => push('📰 [' + (i + 1) + '/' + out.length + '] ' + cut(x.title, 110) + NL + x.source + ' · ' + kst(x.pub, { year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' }).slice(5) + ' KST', x.link, '원문 보기'));
} catch (e) {
  push('📰 반도체 뉴스: ' + FAIL + ' (Google News RSS)', 'https://news.google.com/', 'Google News');
}

return msgs.map((m, i) => ({ json: Object.assign({}, m, i === 0 ? { _commit: { today, cpiPeriod, newsLinks: out.map((x) => x.link) } } : {}) }));

const sends = $input.all();
const ok = sends.length > 0 && sends.every((i) => i.json && i.json.result_code === 0);
let isSchedule = false;
try { isSchedule = $('매일 오전 8시').isExecuted && $execution.mode === 'production'; } catch (e) {}
const plan = $('메시지 구성').first().json._commit;
const sd = $getWorkflowStaticData('global');
let saved = false;
if (isSchedule && ok && plan) {
  sd.lastSentDate = plan.today;
  if (plan.cpiPeriod) { sd.lastCpiPeriod = plan.cpiPeriod; }
  sd.sentNews = (sd.sentNews || []).concat(plan.newsLinks).slice(-100);
  saved = true;
}
return [{ json: { allSent: ok, sentCount: sends.length, failed: sends.filter((i) => !(i.json && i.json.result_code === 0)).length, stateSaved: saved } }];
